#!/usr/bin/env python3
"""Pack props/ai-audio/amb_*.mp3 into props/amb-data.js (window.VN_AMB_ASSETS).

Ambient one-sound beds keyed by background id (filename stem without the
amb_ prefix), consumed by audio.js's ambience layer (E1). Files are embedded
exactly as delivered — no trimming; keep sources short (looping is cheap).
"""
import base64
from pathlib import Path

HERE = Path(__file__).resolve().parent

out = [
    "// Generated by ai-audio/make-amb-data.py — do not edit.",
    "// Ambient sound beds keyed by background id; consumed by the",
    "// audio.js ambience layer. Missing keys = silent (no ambience).",
    "window.VN_AMB_ASSETS = {",
]
total = 0
packed = 0
for f in sorted(HERE.glob("amb_*.mp3")):
    key = f.stem[len("amb_"):]
    data = base64.b64encode(f.read_bytes()).decode()
    total += len(data)
    packed += 1
    out.append(f"  {key}: 'data:audio/mpeg;base64,{data}',")
out.append("};")
(HERE.parent / "amb-data.js").write_text("\n".join(out), encoding="utf-8")
print(f"amb-data.js written: {packed} tracks, base64 payload ~{total // 1024} KB")
